DROP POLICY IF EXISTS "ExpertInvite_readable" ON "ExpertInvite";
CREATE POLICY "ExpertInvite_tenant_isolation" ON "ExpertInvite"
  FOR ALL
  USING ("schoolId" = ANY (string_to_array(current_setting('app.school_ids', true), ',')))
  WITH CHECK ("schoolId" = ANY (string_to_array(current_setting('app.school_ids', true), ',')));

  -- …and the single row whose code somebody has just typed in, which is
  -- how a join code names the school it belongs to.
  -- It is in a SELECT-ONLY policy: readable, never writable.
CREATE POLICY "ExpertInvite_readable" ON "ExpertInvite"
  FOR SELECT
  USING ("schoolId" = ANY (string_to_array(current_setting('app.school_ids', true), ','))
         OR "tokenHash" = current_setting('app.join_code', true)
        );

  -- The token-holder consuming their own live invitation. See the
  -- note in scripts/gen-rls.ts above the ExpertInvite write policy.
DROP POLICY IF EXISTS "ExpertInvite_accept_update" ON "ExpertInvite";
CREATE POLICY "ExpertInvite_accept_update" ON "ExpertInvite"
  FOR UPDATE
  USING (current_setting('app.join_code', true) <> ''
          AND "tokenHash" = current_setting('app.join_code', true)
     AND "acceptedAt" IS NULL
     AND "revokedAt" IS NULL)
  WITH CHECK (current_setting('app.join_code', true) <> ''
          AND "tokenHash" = current_setting('app.join_code', true));

  -- The operator's invitation from an approved expert application: a row
  -- naming no school, written and read back by the superuser alone. See
  -- the expert-registration note in scripts/gen-rls.ts.
DROP POLICY IF EXISTS "ExpertInvite_operator_insert" ON "ExpertInvite";
CREATE POLICY "ExpertInvite_operator_insert" ON "ExpertInvite"
  FOR INSERT
  WITH CHECK ("schoolId" IS NULL AND current_setting('app.is_superuser', true) = '1');
DROP POLICY IF EXISTS "ExpertInvite_operator_read" ON "ExpertInvite";
CREATE POLICY "ExpertInvite_operator_read" ON "ExpertInvite"
  FOR SELECT
  USING ("schoolId" IS NULL AND current_setting('app.is_superuser', true) = '1');

